by: "recommend", direction: "asc" } } if(!res.product_info.product.length) return; this.model.total
= res.product_info.product.length; this.product_display = res.home_page_info.product_display;
this.discount_info = res.discount_info; res.product_info.product.forEach((product) => { product.url
= appDiscountUtils.globalizePath(product.url); })
SPZ.whenApiDefined(document.getElementById("appDiscountIndexFlashsale")) .then(apis => {
apis.render(res).then(() => { const hiddenArraw = res.home_page_info.banner.enabled ?
res.product_info.product.length < 5 : res.product_info.product.length < 6 if(hiddenArraw) {
document.querySelectorAll('.app_discount_flashsale_arrow').forEach((item) => {
item.style.display="none"; }) }
SPZ.whenApiDefined(document.getElementById("flashsaleProductsRender")).then((api) => {
res.product_info.product_display = this.product_display; res.product_info.discount_id =
this.discount_id; res.product_info.apply_scenario = 1; res.product_info.limit_purchase =
