}).catch(err => { console.error(err); }) return data; }; // 获取加载的商品数据，拼接html模板 async
loadData(cb) { // 请求数据 this.model.loading = true; //查询活动商品接口 const reqBody = {
discount_id: this.discount_id, page: this.model.page, limit: this.model.limit, apply_scenario: 1,
sort: this.model.params.sort, sales_channel: { sale_channel_type: "online", sale_channel_id:
