this.product_display; res.discount_id = this.discount_id; res.apply_scenario = 1; res.limit_purchase
= this.discount_info.limit_user_product_discount; res.discount_image_size = this.image_size; //
获取商品列表渲染模板, dom挂载 const $content =
document.querySelector(".app_discount_products_list_wrapper"); this.templates_ =
SPZServices.templatesForDoc();
this.templates_.renderTemplate(document.querySelector('#apps-discounts_product_list_template'),
res).then((el) => { const childNodes = el.querySelectorAll('.as-render-product-item'); if
(childNodes && childNodes.length > 0) { $content.append(...childNodes); } }) // 监听load去掉灰色背景
