window.lazyLoadInstance && window.lazyLoadInstance.update(); } } this.model.loading = false;
}).catch((err)=>{ console.error(err); this.model.loading = false; }) }; setupAction_() {
this.registerAction('shiftMove', (data) => { const $el =
