document.querySelector('#quick-shop-flashsale-tip'); SPZ.whenApiDefined(flashsaleEl).then((api) => {
api.render(data); }); } bindEvent_() { // 监听滚动，请求数据 const $el =
document.querySelector(".app_discount_products_list_wrapper"); if($el) {
$el.addEventListener("scroll", this.win.SPZCore.Types.debounce( this.win, () => { const isRightEnd =
$el.scrollLeft + $el.offsetWidth + 10 >= $el.scrollWidth; const isLeftEnd = Math.abs($el.scrollLeft)
+ $el.offsetWidth + 10 >= $el.scrollWidth; const isRTL =
document.documentElement.getAttribute('dir') == 'rtl'; const isEnd = isRTL ? isLeftEnd : isRightEnd;
if(isEnd && this.model.params.has_more && !this.model.loading && this.model.total < 100) {
this.loadData(); } }, 50 )) }; }; buildCallback() { this.setupAction_(); }; mountCallback() { const
$el = document.querySelector("#appDiscountFlashsale") this.discount_id =
$el.getAttribute('flashsale-id'); this.image_size = $el.getAttribute('image-size');
if(!this.discount_id) return; this.getDiscountList(); }; }
